import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"第十九卦 臨 地澤臨 坤上兌下","description":"周易 - 第十九卦 臨 地澤臨 坤上兌下","frontmatter":{"title":"第十九卦 臨 地澤臨 坤上兌下","description":"周易 - 第十九卦 臨 地澤臨 坤上兌下"},"headers":[],"relativePath":"classics/zhouyi/020.md","filePath":"classics/zhouyi/020.md"}'),l={name:"classics/zhouyi/020.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="臨" tabindex="-1">臨 <a class="header-anchor" href="#臨" aria-label="Permalink to “臨”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>元，亨，利，貞。至於八月有兇。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>臨，剛浸而長。說而順，剛中而應，大亨以正，天之道也。至於八月有兇，消不久也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>澤上有地，臨；君子以教思無窮，容保民無疆。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>鹹臨，貞吉。象曰：鹹臨 貞吉，志行正也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>鹹臨，吉無不利。象曰：鹹臨，吉無不利；未順命也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>甘臨，無攸利。既憂之，無咎。象曰：甘臨，位不當也。既憂之，咎不長也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>至臨，無咎。象曰：至臨無咎，位當也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>知臨，大君之宜，吉。象曰：大君之宜，行中之謂也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>敦臨，吉無咎。象曰：敦臨之吉，志在內也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
